use std::io::{self,BufRead,Write};
fn main(){let mode=std::env::args().nth(1).unwrap_or_default();let mut stdin=io::stdin().lock();if mode=="startup"||mode=="late"{let mut token=String::new();stdin.read_line(&mut token).unwrap();if token!="token\n"{std::process::exit(3)}}if mode=="late"{std::thread::sleep(std::time::Duration::from_millis(600));}println!("12345");io::stdout().flush().unwrap();if mode=="gone" {return}let mut line=String::new();stdin.read_line(&mut line).unwrap();if line!="shutdown\n"{std::process::exit(2)}if mode=="slow" {std::thread::sleep(std::time::Duration::from_millis(600));}if mode=="retry" {println!("ERROR");io::stdout().flush().unwrap();let mut second=String::new();stdin.read_line(&mut second).unwrap();if second!="shutdown\n" {std::process::exit(4)}}if mode=="bad"{println!("ERROR");io::stdout().flush().unwrap();std::thread::sleep(std::time::Duration::from_secs(5));return}if mode=="noack"{return}println!("OK");io::stdout().flush().unwrap();if mode=="badexit"{std::process::exit(7)}}
